  [CategoryTheory.Category.{v₁, u₁} C] {D : Type u₂} [CategoryTheory.Category.{v₂, u₂} D] {T : D}
  {S : CategoryTheory.Functor C D} {A : Type u₃} [CategoryTheory.Category.{v₃, u₃} A] {B : Type u₄}
  [CategoryTheory.Category.{v₄, u₄} B] {U : CategoryTheory.Functor A B} {V : B}
  {F : CategoryTheory.Functor C A} {G : CategoryTheory.Functor D B} (α : F.comp U ⟶ S.comp G)
  (β : G.obj T ⟶ V) (X : CategoryTheory.Comma S (CategoryTheory.Functor.fromPUnit T)) :
  ((CategoryTheory.CostructuredArrow.map₂ α β).obj X).right = X.right

theorem CategoryTheory.CostructuredArrow.map_obj_right.{v₁, v₂, u₁, u₂} {C : Type u₁}
  [CategoryTheory.Category.{v₁, u₁} C] {D : Type u₂} [CategoryTheory.Category.{v₂, u₂} D] {T T' : D}
  {S : CategoryTheory.Functor C D} (f : T ⟶ T')
  (X : CategoryTheory.Comma S (CategoryTheory.Functor.fromPUnit T)) :
  ((CategoryTheory.CostructuredArrow.map f).obj X).right = X.right

theorem CategoryTheory.StructuredArrow.map_obj_left.{v₁, v₂, u₁, u₂} {C : Type u₁}
  [CategoryTheory.Category.{v₁, u₁} C] {D : Type u₂} [CategoryTheory.Category.{v₂, u₂} D] {S S' : D}
  {T : CategoryTheory.Functor C D} (f : S ⟶ S')
  (X : CategoryTheory.Comma (CategoryTheory.Functor.fromPUnit S') T) :
  ((CategoryTheory.StructuredArrow.map f).obj X).left = X.left

theorem CategoryTheory.CostructuredArrow.mapIso_inverse_map_left.{v₁, v₂, u₁, u₂} {C : Type u₁}
  [CategoryTheory.Category.{v₁, u₁} C] {D : Type u₂} [CategoryTheory.Category.{v₂, u₂} D] {T T' : D}
  {S : CategoryTheory.Functor C D} (i : T ≅ T')
  {Y✝ X✝ : CategoryTheory.Comma S (CategoryTheory.Functor.fromPUnit T')} (f : Y✝ ⟶ X✝) :
  ((CategoryTheory.CostructuredArrow.mapIso i).inverse.map f).left = f.left

theorem CategoryTheory.CostructuredArrow.essSurj_map₂.{v₁, v₂, v₃, v₄, u₁, u₂, u₃, u₄} {C : Type u₁}
  [CategoryTheory.Category.{v₁, u₁} C] {D : Type u₂} [CategoryTheory.Category.{v₂, u₂} D] {T : D}
  {S : CategoryTheory.Functor C D} {A : Type u₃} [CategoryTheory.Category.{v₃, u₃} A] {B : Type u₄}
  [CategoryTheory.Category.{v₄, u₄} B] {U : CategoryTheory.Functor A B} {V : B}
  {F : CategoryTheory.Functor C A} {G : CategoryTheory.Functor D B} (α : F.comp U ⟶ S.comp G)
  (β : G.obj T ⟶ V) [F.EssSurj] [G.Full] [CategoryTheory.IsIso α] [CategoryTheory.IsIso β] :
  (CategoryTheory.CostructuredArrow.map₂ α β).EssSurj
